<?php
namespace ServSys\ServiceCalls;
use ServSys\FlatRate\FlatRateConfigRepository;
use ServSys\FlatRate\FlatRateItemRepository;
use ServSys\FlatRate\FlatRateMaterialRepository;
use ServSys\FlatRate\FlatRatePricingEngine;
use ServSys\Inventory\InventoryItemRepository;
if ( ! defined( 'ABSPATH' ) ) { exit; }
final class ServiceCallChargeService {
 private $charges; private $calls; private $items; private $materials; private $configs; private $inventory;
 public function __construct(ServiceCallChargeRepository $charges=null,ServiceCallRepository $calls=null,FlatRateItemRepository $items=null,FlatRateMaterialRepository $materials=null,FlatRateConfigRepository $configs=null,InventoryItemRepository $inventory=null){$this->charges=$charges?:new ServiceCallChargeRepository();$this->calls=$calls?:new ServiceCallRepository();$this->items=$items?:new FlatRateItemRepository();$this->materials=$materials?:new FlatRateMaterialRepository();$this->configs=$configs?:new FlatRateConfigRepository();$this->inventory=$inventory?:new InventoryItemRepository();}
 public function create_flat_rate(int $service_call_id,int $flat_rate_item_id,string $price_type,float $quantity=1.0): int {
  $call=$this->require_call($service_call_id);$item=$this->items->find($flat_rate_item_id);if(!$item||(int)$item['company_id']!==(int)$call['company_id']){throw new \InvalidArgumentException('Flat Rate item does not belong to this Service Call company.');}if(empty($item['active'])){throw new \InvalidArgumentException('Inactive Flat Rate items cannot be added to a Service Call.');}
  $quantity=$this->quantity($quantity);$config=$this->configs->current();if(!$config){throw new \InvalidArgumentException('Flat Rate pricing configuration is required before adding a Flat Rate charge.');}
  $material_cost=0.0;foreach($this->materials->for_item($flat_rate_item_id) as $material){$qty=(float)$material['quantity'];if(!empty($material['inventory_item_id'])){$inventory=$this->inventory->find((int)$material['inventory_item_id']);if(!$inventory){throw new \InvalidArgumentException('A Flat Rate recipe inventory item is unavailable for this company.');}$unit_cost=(float)$inventory['unit_cost'];}else{$unit_cost=(float)$material['manual_unit_cost'];}$material_cost+=$qty*$unit_cost;}
  $pricing=FlatRatePricingEngine::calculate((float)$item['labor_hours'],(float)$config['labor_rate'],$material_cost,(float)$config['part_markup_multiplier'],(float)$config['sales_tax_percent'],$price_type,(float)$config['additional_repair_multiplier'],(float)$config['agreement_repair_multiplier'],(float)$config['commercial_multiplier'],!empty($item['no_discount']));
  $data=array('service_call_id'=>$service_call_id,'source_type'=>'flat_rate','flat_rate_item_id'=>$flat_rate_item_id,'flat_rate_code_snapshot'=>(int)$item['code'],'description_snapshot'=>$item['description'],'customer_notes_snapshot'=>$item['customer_notes'],'price_type_snapshot'=>$pricing['price_type'],'quantity'=>$quantity,'labor_hours_snapshot'=>(float)$item['labor_hours'],'labor_rate_snapshot'=>(float)$config['labor_rate'],'material_cost_snapshot'=>$pricing['material_cost'],'part_markup_multiplier_snapshot'=>(float)$config['part_markup_multiplier'],'material_selling_total_snapshot'=>$pricing['material_selling_total'],'sales_tax_percent_snapshot'=>(float)$config['sales_tax_percent'],'sales_tax_snapshot'=>$pricing['sales_tax'],'base_price_snapshot'=>$pricing['base_price'],'price_multiplier_snapshot'=>$pricing['price_multiplier'],'unit_price_snapshot'=>$pricing['price'],'extended_price'=>round($pricing['price']*$quantity,4),'no_discount_snapshot'=>!empty($item['no_discount'])?1:0,'special_item_snapshot'=>!empty($item['special_item'])?1:0);
  return $this->persist($data);
 }
 public function create_manual(int $service_call_id,string $description,float $quantity,float $unit_price,string $notes=''): int {$this->require_call($service_call_id);$description=sanitize_text_field($description);if(''===$description){throw new \InvalidArgumentException('Charge description is required.');}$quantity=$this->quantity($quantity);if($unit_price<0){throw new \InvalidArgumentException('Manual charge unit price cannot be negative.');}$unit_price=round($unit_price,4);return $this->persist(array('service_call_id'=>$service_call_id,'source_type'=>'manual','flat_rate_item_id'=>null,'flat_rate_code_snapshot'=>null,'description_snapshot'=>$description,'customer_notes_snapshot'=>sanitize_textarea_field($notes),'price_type_snapshot'=>null,'quantity'=>$quantity,'labor_hours_snapshot'=>0,'labor_rate_snapshot'=>0,'material_cost_snapshot'=>0,'part_markup_multiplier_snapshot'=>1,'material_selling_total_snapshot'=>0,'sales_tax_percent_snapshot'=>0,'sales_tax_snapshot'=>0,'base_price_snapshot'=>$unit_price,'price_multiplier_snapshot'=>1,'unit_price_snapshot'=>$unit_price,'extended_price'=>round($unit_price*$quantity,4),'no_discount_snapshot'=>0,'special_item_snapshot'=>0));}
 private function require_call(int $id): array {$call=$this->calls->find($id);if(!$call){throw new \InvalidArgumentException('Service Call does not belong to the current company.');}return $call;}
 private function quantity(float $quantity): float {if($quantity<=0){throw new \InvalidArgumentException('Charge quantity must be greater than zero.');}return round($quantity,4);}
 private function persist(array $data): int {$data['created_at']=current_time('mysql',true);$data['created_by']=get_current_user_id()?:null;$id=$this->charges->create($data);if(!$id){throw new \RuntimeException('Unable to save Service Call charge.');}return $id;}
}
